package com.muxigame.city;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public final class CityTestsMaintenance {
 @GameTest(template="empty") public static void communalFoodAndNoDoubleCount(GameTestHelper h){try(var f=new CityTestsSupply.Fixture(h)){var d=CityMaintenance.get(f.server);var p=new CityMaintenance.Plan();p.collective=true;p.warehouse=f.food;p.healthyPlots=80;long money=f.money();try{for(int i=0;i<2;i++){var w=new CityMaintenance.Worker();w.city=f.c.id;w.enabled=true;w.role="农民";w.blocks=new ArrayList<>(CityMaintenance.FARM);d.state.workers.put(f.people.get(i),w);}for(int i=0;i<60;i++)d.food(f.server,f.c,p);h.assertTrue(f.count(f.food,"minecraft:bread")==26&&f.count(f.food,"minecraft:wheat")==2,"80 city plots yield 80 wheat, 26 bread plus two wheat; two farmers cannot duplicate plots");h.assertTrue(f.money()==money&&!f.l.hasChunkAt(f.pos),"No minted money, no forced chunks");}finally{f.people.forEach(d.state.workers::remove);}}h.succeed();}
 @GameTest(template="empty",timeoutTicks=80) public static void actualRepairDelayAndResponsibility(GameTestHelper h){var f=new CityTestsSupply.Fixture(h);var d=CityMaintenance.get(f.server);var pos=h.absolutePos(new BlockPos(1,2,1));f.c.bounds=CityBounds.between(pos,pos.offset(2,0,0));var p=new CityMaintenance.Plan();p.baseline.put(pos.asLong(),CityMaintenance.encode(Blocks.STONE.defaultBlockState()));p.baseline.put(pos.east().asLong(),CityMaintenance.encode(Blocks.GRASS_BLOCK.defaultBlockState()));d.state.cities.put(f.c.id,p);var farmer=new CityMaintenance.Worker();farmer.city=f.c.id;farmer.enabled=true;farmer.role="农民";farmer.blocks=new ArrayList<>(CityMaintenance.FARM);farmer.next=f.l.getGameTime()+200;d.state.workers.put(f.people.get(0),farmer);var artisan=new CityMaintenance.Worker();artisan.city=f.c.id;artisan.enabled=true;artisan.role="工匠";artisan.artisan=true;artisan.perHour=3600;artisan.next=f.l.getGameTime()+20;d.state.workers.put(f.people.get(1),artisan);f.l.setBlock(pos,Blocks.AIR.defaultBlockState(),2);f.l.setBlock(pos.east(),Blocks.AIR.defaultBlockState(),2);CityMaintenance.tick(f.server);h.assertTrue(f.l.getBlockState(pos).isAir(),"Repair requires time");h.runAfterDelay(30,()->{var duty=WorkHours.config(f.server,f.people.getFirst());duty.start=(int)((Math.floorMod(RuralSettlement.dayTime(f.server,f.c),24000)/1000+6)%24);duty.end=(duty.start+2)%24;try{for(int i=0;i<Math.max(32,d.state.cities.size()*4+4);i++)CityMaintenance.tick(f.server);h.assertTrue(f.l.getBlockState(pos).is(Blocks.STONE),"Artisan restores actual wall");h.assertTrue(f.l.getBlockState(pos.east()).isAir(),"Artisan cannot take farmer-owned blocks");var saved=d.save(new CompoundTag(),f.l.registryAccess());var restored=CityMaintenance.load(saved,f.l.registryAccess());h.assertTrue(restored.state.cities.get(f.c.id).baseline.equals(p.baseline),"Completion baseline survives save/reload");}finally{d.state.cities.remove(f.c.id);f.people.forEach(d.state.workers::remove);f.close();}h.succeed();});}
 @GameTest(template="empty") public static void growthAndContainerRules(GameTestHelper h){h.assertTrue(CityMaintenance.same(Blocks.WHEAT.defaultBlockState(),Blocks.WHEAT.defaultBlockState().setValue(net.minecraft.world.level.block.CropBlock.AGE,7)),"Crop growth is not damage");h.assertTrue(CityMaintenance.same(Blocks.WATER.defaultBlockState(),Blocks.WATER.defaultBlockState().setValue(net.minecraft.world.level.block.LiquidBlock.LEVEL,3)),"Water flow is not perpetual damage");var w=new CityMaintenance.Worker();w.city=UUID.randomUUID();w.artisan=true;h.assertTrue(!CityMaintenance.matches(w,"minecraft:wheat",Set.of("minecraft:wheat"))&&CityMaintenance.matches(w,"minecraft:stone",Set.of("minecraft:wheat")),"Complement scope is exact");var bad=new CityMaintenance.State();bad.workers.put(UUID.randomUUID(),w);w.perHour=0;CityTestsSimulation.reject(h,()->CityMaintenance.validate(bad));h.succeed();}
 @GameTest(template="empty") public static void wheatMigrationPreservesCounts(GameTestHelper h){var source=com.google.gson.JsonParser.parseString("{\"goods\":{\"city_settlements:rice\":4,\"minecraft:wheat\":3},\"resourceSource\":\"rice\",\"archivedEntity\":\"{id:city_settlements:cooked_rice}\"}");var converted=CityWheatMigration.convert(source).getAsJsonObject();h.assertTrue(converted.getAsJsonObject("goods").get("minecraft:wheat").getAsInt()==7&&converted.get("resourceSource").getAsString().equals("wheat")&&converted.get("archivedEntity").getAsString().contains("minecraft:bread"),"Mixed stocks and archived IDs migrate without loss");var old=new net.minecraft.world.item.ItemStack(CityMod.RICE_SEEDS.get(),12);var next=CityWheatMigration.convert(old);h.assertTrue(next.is(net.minecraft.world.item.Items.WHEAT_SEEDS)&&next.getCount()==12&&old.getCount()==12,"Migration preserves stack count and original input");h.succeed();}
 @GameTest(template="empty") public static void unloadedRepairIsDataFirst(GameTestHelper h){try(var f=new CityTestsSupply.Fixture(h)){var d=CityMaintenance.get(f.server);var p=new CityMaintenance.Plan();p.baseline.put(f.pos.asLong(),CityMaintenance.encode(Blocks.STONE.defaultBlockState()));p.damaged.add(f.pos.asLong());d.state.cities.put(f.c.id,p);var w=new CityMaintenance.Worker();w.city=f.c.id;w.enabled=true;w.artisan=true;w.role="工匠";w.next=Math.max(1,f.l.getGameTime()-1);d.state.workers.put(f.people.getFirst(),w);var duty=WorkHours.config(f.server,f.people.getFirst());duty.start=(int)((Math.floorMod(RuralSettlement.dayTime(f.server,f.c),24000)/1000+6)%24);duty.end=(duty.start+2)%24;try{for(int i=0;i<Math.max(32,d.state.cities.size()*4+4);i++)CityMaintenance.tick(f.server);h.assertTrue(p.ready.contains(f.pos.asLong())&&p.repaired==1&&!f.l.hasChunkAt(f.pos),"Unloaded repair finishes in data and queues physical projection without chunk loading");var restored=CityMaintenance.load(d.save(new CompoundTag(),f.l.registryAccess()),f.l.registryAccess());h.assertTrue(restored.state.cities.get(f.c.id).ready.contains(f.pos.asLong()),"Pending projection survives restart");}finally{d.state.cities.remove(f.c.id);d.state.workers.remove(f.people.getFirst());}}h.succeed();}

}
